GO

CREATE VIEW [dbo].[EmployeeAccess]

AS

	SELECT
		EmployeeKey AS EmployeeId,
		CASE
			WHEN ea.UnitLevelKey = 6 THEN 'Company'
			WHEN ea.UnitLevelKey = 5 THEN 'Department'
			WHEN ea.UnitLevelKey = 4 THEN 'SubUnit'
			WHEN ea.UnitLevelKey = 3 THEN 'BusinessUnit'
			WHEN ea.UnitLevelKey = 2 THEN 'BusinessDivision'
			WHEN ea.UnitLevelKey = 1 THEN 'BusinessArea'
			WHEN ea.UnitLevelKey = 0 THEN 'Group'
			ELSE ''
		END AS LevelName,
		CASE
			WHEN ea.UnitLevelKey = 6 THEN comp.CompanyId
			WHEN ea.UnitLevelKey = 5 THEN ot.TeamId
			WHEN ea.UnitLevelKey = 4 THEN dept.DepartmentId
			WHEN ea.UnitLevelKey = 3 THEN bu.BusinessUnitId
			WHEN ea.UnitLevelKey = 2 THEN div.DivisionId
			WHEN ea.UnitLevelKey = 1 THEN ba.BusinessAreaId
			WHEN ea.UnitLevelKey = 0 THEN '0'
			ELSE ''
		END [Level],
		CASE
			WHEN ea.UnitLevelKey = 5 THEN ot.CompanyId
			WHEN ea.UnitLevelKey = 4 THEN dept.BusinessAreaId
			WHEN ea.UnitLevelKey = 3 THEN bu.BusinessAreaId
			WHEN ea.UnitLevelKey = 2 THEN div.BusinessAreaId
			ELSE ''
		END [ParentId],
		CASE
			WHEN ea.UnitLevelKey = 5 THEN '99'
			WHEN ea.UnitLevelKey BETWEEN 2 AND 4 THEN '1'
			ELSE ''
		END [ParentLevel],
		CASE
			WHEN ea.UnitLevelKey = 5 THEN 'Company'
			WHEN ea.UnitLevelKey BETWEEN 2 AND 4 THEN 'BusinessArea'
			ELSE ''
		END [ParentLevelname],
		AccessLevelId AS AccessLevel,
		AccessRoleKey AS AccessRoleId,
		AccessAdditionId AS AccessAddition,
		src_ChangedTime AS Changed,
		inheritedOUL.UnitLevelId AS InheritedFrom,
		src_RowKey AS EmployeeAccessId,
		EmployeeAccessKey AS RowId,
		oul.UnitLevelId AS unitLevelId
	FROM swecocore.CoreData.EmployeeAccess ea
	JOIN swecocore.Core.OrgUnitLevel oul on ea.UnitLevelKey = oul.UnitLevelKey
	LEFT JOIN swecocore.Core.OrgUnitLevel inheritedOUL on ea.InheritedFromUnitLevelKey = inheritedOUL.UnitLevelKey
	LEFT JOIN swecocore.Core.OrgCompany comp on ea.UnitLevelKey = 6 and ea.UnitKey = comp.CompanyKey
	LEFT JOIN swecocore.Core.OrgTeam ot on ea.UnitLevelKey = 5 and ea.UnitKey = ot.TeamKey
	LEFT JOIN swecocore.Core.OrgDepartment dept on ea.UnitLevelKey = 4 and ea.UnitKey = dept.DepartmentKey
	LEFT JOIN swecocore.Core.OrgBusinessUnit bu on ea.UnitLevelKey = 3 and ea.UnitKey = bu.BusinessUnitKey
	LEFT JOIN swecocore.Core.OrgDivision div on ea.UnitLevelKey = 2 and ea.UnitKey = div.DivisionKey
	LEFT JOIN swecocore.Core.OrgBusinessArea ba on ea.UnitLevelKey = 1 and ea.UnitKey = ba.BusinessAreaKey
	
GO
