CREATE   VIEW [CoreX].[EmployeeAccess]
	AS
	WITH EmpAcc
	AS
	(
	SELECT
	   ea.EmployeeKey
	  ,ea.UnitLevelKey --sewaah
	  ,ea.UnitKey
	  ,ea.AccessLevelId
	  ,ea.AccessAdditionId
	  ,rt.AccessRestrictionTypeKey
	  ,rt.AccessRestrictionTypeName
	  ,ea.AccessRestrictionOptionKey
	  ,ro.AccessRestrictionOptionName
	  ,ea.InheritedFromUnitLevelKey
	  ,ea.src_RowKey
	  ,ea.src_ChangedTime
	  ,e.LoginId
	  --,e.Login AS EmployeeId  --Removed by sepika 2022-04-12 15:20, as LoginId replaces it.
	  ,e.Domain
	  ,e.[Login]
	  ,e.FirstName
	  ,e.LastName
	  ,e.Firstname + ', ' + e.Lastname AS FullName
	  ,rbk_OrgUnit = 
			CASE WHEN ea.UnitLevelKey = 6  THEN comp.OrgUnitId
				 WHEN ea.UnitLevelKey = 5  THEN ot.OrgUnitId
				 WHEN ea.UnitLevelKey = 4  THEN dept.OrgUnitId
				 WHEN ea.UnitLevelKey = 3  THEN bu.OrgUnitId
				 WHEN ea.UnitLevelKey = 2  THEN div.OrgUnitId
				 WHEN ea.UnitLevelKey = 1  THEN ba.OrgUnitId
				 WHEN ea.UnitLevelKey = 0  THEN '0'
				 ELSE NULL END
	  ,UnitId = 
			CASE WHEN ea.UnitLevelKey = 6  THEN comp.CompanyId
				 WHEN ea.UnitLevelKey = 5  THEN ot.TeamId
				 WHEN ea.UnitLevelKey = 4  THEN dept.DepartmentId
				 WHEN ea.UnitLevelKey = 3  THEN bu.BusinessUnitId
				 WHEN ea.UnitLevelKey = 2  THEN div.DivisionId
				 WHEN ea.UnitLevelKey = 1  THEN ba.BusinessAreaId
				 WHEN ea.UnitLevelKey = 0  THEN '0'
				 ELSE NULL END				   
	  ,ParentId = 
			CASE WHEN ea.UnitLevelKey = 6  THEN comp.CompanyId
				 WHEN ea.UnitLevelKey = 5  THEN ot.CompanyId
				 WHEN ea.UnitLevelKey = 4  THEN dept.BusinessAreaId
				 WHEN ea.UnitLevelKey = 3  THEN bu.BusinessAreaId
				 WHEN ea.UnitLevelKey = 2  THEN div.BusinessAreaId
				 WHEN ea.UnitLevelKey = 1  THEN ba.BusinessAreaId
				 WHEN ea.UnitLevelKey = 0  THEN '0'
				 ELSE NULL END	  
	  -- Should not be part of the view according to Arnold
	  --,ParentOrgUnitId = 
			--CASE WHEN ea.UnitLevelKey = 6 THEN comp.ParentOrgUnitId
			--	 WHEN ea.UnitLevelKey = 5 THEN ot.ParentOrgUnitId
			--	 WHEN ea.UnitLevelKey = 4 THEN dept.ParentOrgUnitId
			--	 WHEN ea.UnitLevelKey = 3 THEN bu.ParentOrgUnitId
			--	 WHEN ea.UnitLevelKey = 2 THEN div.ParentOrgUnitId
			--	 WHEN ea.UnitLevelKey = 1 THEN ba.ParentOrgUnitId
			--	 WHEN ea.UnitLevelKey = 0 THEN '0'
			--	 ELSE NULL END
	  --,ParentBusinessAreaId = 
			--CASE WHEN ea.UnitLevelKey = 6 THEN comp.CompanyId
			--	 WHEN ea.UnitLevelKey = 5 THEN ot.BusinessAreaId
			--	 WHEN ea.UnitLevelKey = 4 THEN dept.BusinessAreaId
			--	 WHEN ea.UnitLevelKey = 3 THEN bu.BusinessAreaId
			--	 WHEN ea.UnitLevelKey = 2 THEN div.BusinessAreaId
			--	 WHEN ea.UnitLevelKey = 1 THEN ba.BusinessAreaId
			--	 WHEN ea.UnitLevelKey = 0 THEN '0'
			--	 ELSE NULL END				   
	  ,UnitName = 
			CASE WHEN ea.UnitLevelKey = 6  THEN comp.CompanyName
				 WHEN ea.UnitLevelKey = 5  THEN ot.TeamName
				 WHEN ea.UnitLevelKey = 4  THEN dept.DepartmentName
				 WHEN ea.UnitLevelKey = 3  THEN bu.BusinessUnitName
				 WHEN ea.UnitLevelKey = 2  THEN div.DivisionName
				 WHEN ea.UnitLevelKey = 1  THEN ba.BusinessAreaName
				 WHEN ea.UnitLevelKey = 0  THEN '0'
				 ELSE NULL END
	  ,ar.AccessRoleKey
	  ,ar.AccessRoleName
	  ,oul.UnitLevelId
	  ,CASE
			WHEN ea.UnitLevelKey = 6  THEN 'Company'
			WHEN ea.UnitLevelKey = 5  THEN 'Team'
			WHEN ea.UnitLevelKey = 4  THEN 'Department'
			WHEN ea.UnitLevelKey = 3  THEN 'BusinessUnit'
			WHEN ea.UnitLevelKey = 2  THEN 'Division'
			WHEN ea.UnitLevelKey = 1  THEN 'BusinessArea'
			WHEN ea.UnitLevelKey = 0  THEN 'Group'
			ELSE ''
		END AS UnitLevelName
	   ,ea.AccessLevelId AS AccessLevel
	   ,ea.src_ChangedTime AS ChangedTime
	   ,COALESCE(ot.Active, dept.Active, bu.Active, div.Active, ba.Active, comp.Active, 1) AS IsActiveUnit
	   ,CASE WHEN inheritedOUL.UnitLevelKey IS NOT NULL THEN 1 ELSE 0 END IsInherited
	   ,inheritedOUL.UnitLevelName InheritedFromUnitLevelName
	   ,ea.ValidFromDate
	   ,ea.ValidToDate
	   ,ea.[md_InsertedTime]
       ,ea.[md_InsertedBy]
       ,ea.[md_ChangedTime]
       ,ea.[md_ChangedBy]
       ,ea.[md_RowVersion]
       ,ea.[md_RowState]
       ,ea.[md_SourceId]
       ,ea.[md_StgRowId]
       ,ea.[md_LoadJobId]
       ,ea.[md_DqLevel]
       ,ea.[md_DqIssueDescription]
       ,ea.[md_BPK]
	FROM [Core].[EmployeeAccess] ea
	LEFT JOIN [Core].[OrgUnitLevel] oul on ea.UnitLevelKey = oul.UnitLevelKey
	LEFT JOIN [Core].[Employee] e ON ea.EmployeeKey = e.EmployeeKey
	LEFT JOIN [Core].[AccessRole] ar ON ea.AccessRoleKey = ar.AccessRoleKey
	LEFT JOIN [Core].[OrgUnitLevel] inheritedOUL on ea.InheritedFromUnitLevelKey = inheritedOUL.UnitLevelKey
	LEFT JOIN [Core].[OrgCompany] comp on ea.UnitLevelKey = 6 and ea.UnitKey = comp.CompanyKey
	LEFT JOIN [Core].[OrgTeam] ot on ea.UnitLevelKey = 5 and ea.UnitKey = ot.TeamKey
	LEFT JOIN [Core].[OrgDepartment] dept on ea.UnitLevelKey = 4 and ea.UnitKey = dept.DepartmentKey
	LEFT JOIN [Core].[OrgBusinessUnit] bu on ea.UnitLevelKey = 3 and ea.UnitKey = bu.BusinessUnitKey
	LEFT JOIN [Core].[OrgDivision] div on ea.UnitLevelKey = 2 and ea.UnitKey = div.DivisionKey
	LEFT JOIN [Core].[OrgBusinessArea] ba on ea.UnitLevelKey = 1 and ea.UnitKey = ba.BusinessAreaKey
	LEFT join [Core].[AccessRestriction]  ro on ea.AccessRestrictionOptionKey = ro.AccessRestrictionOptionKey
	LEFT join [Core].[AccessRestrictionType] rt on ro.AccessRestrictionTypeKey = rt.AccessRestrictionTypeKey
	--WHERE oul.UnitLevelId = 1
)

	SELECT
		 [EmployeeKey]
		 ,UnitLevelKey
		 ,UnitKey
		 ,AccessLevelId
		 ,AccessAdditionId
		 ,AccessRestrictionTypeKey
		 ,AccessRestrictionTypeName
		 ,AccessRestrictionOptionKey
		 ,AccessRestrictionOptionName
		,[LoginId]
		--,[EmployeeId]  Removed by sepika 2022-04-12 15:20, as LoginId replaces it.
		,[Domain]
		,[Login]
		,[FirstName]
		,[LastName]
		,[FullName]
		,[rbk_OrgUnit]
		,[UnitId]			   			   
		,[UnitName]
		,[ParentId]
		,[AccessRoleKey]
		,[AccessRoleName]
		,[UnitLevelId]
		,[UnitLevelName]
		,[AccessLevel]
		,[ChangedTime]
		,[IsActiveUnit]
		,[IsInherited]
		,[InheritedFromUnitLevelName]
		,[ValidFromDate]
		,[ValidToDate]
		,[md_InsertedTime]
		,[md_InsertedBy]
		,[md_ChangedTime]
		,[md_ChangedBy]
		,[md_RowVersion]
		,[md_RowState]
		,[md_SourceId]
		,[md_StgRowId]
		,[md_LoadJobId]
		,[md_DqLevel]
		,[md_DqIssueDescription]
		,[md_BPK]
	FROM EmpAcc
	WHERE
		[rbk_OrgUnit] IS NOT NULL
GO
