CREATE VIEW [CoreX].[SubCategoryFunction] AS
SELECT
	sc.SubCategoryKey, 
	sc.SubCategoryCode,
	sc.SubCategoryName,
	c.CategoryKey,
	c.CategoryCode,
	c.CategoryName,
	ct.CategoryTypeKey,
	ct.CategoryTypeName
FROM [CoreData].CategoryType AS ct
INNER JOIN [CoreData].Category AS c ON ct.CategoryTypeKey = c.CategoryTypeKey
INNER JOIN [CoreData].SubCategory AS sc ON sc.CategoryKey = c.CategoryKey
WHERE ct.CategoryTypeName = 'Function';
