/*
================================================================= 

View name:	[dbo].[v2EmployeeFunction]

Purpose:	Expose one single function per employee (old structure!) 
			There is actually no way to prioritise between multiple functions, so we will just pick the one with the highest id.
			Use in Corex.Employee until all countries are on new structure

================================================================= 

Changes:  2022-07-22	SEARNO	Created

================================================================= 

*/
CREATE VIEW [dbo].[v2EmployeeFunction] AS

SELECT 
	F.EmployeeId, 
	SC.SubCategoryCode as SubCategoryFunctionLocalId, 
	SC.SubCategoryName as SubCategoryFunctionLocalName,
	SC.CategoryCode as CategoryFunctionLocalId,
	SC.CategoryName as CategoryFunctionLocalName

FROM
(
	SELECT DISTINCT EF.EmployeeId, MAX(EF.FunctionID) OVER (PARTITION BY EF.EmployeeId) AS FunctionId
	FROM EmployeeFunction EF 
) as F
	JOIN Corex.SubCategoryFunction SC ON SC.SubCategoryKey = F.FunctionId
GO
