CREATE VIEW [Core].[Employment]
AS
SELECT
	 [EmploymentKey]	
	,[EmployeeKey]					
	,[HireDate]					
	,[TerminationDate]			
	,[ValidFromDate]			
	,[ValidToDate]				
	,[CompanyId]					
	,[EmploymentContractTypeKey]
	,[EmploymentContractSubTypeKey]
	,[WorkingCountryKey]
	,[IsAutoGeneratedValidFromDate]
	,CONVERT([int],CASE WHEN CONVERT(date, GETDATE()) BETWEEN [HireDate] and ISNULL([TerminationDate], '2099-12-31') THEN (1) ELSE  
									CASE WHEN [HireDate] > CONVERT(date, GETDATE()) THEN (2) ELSE 	
									CASE WHEN [HireDate] > [TerminationDate] THEN (-1) ELSE (0) END END END ) AS [StatusKey]	
	,[src_ChangedBy]		
	,[src_ChangedTime]	
	,[md_InsertedTime]	
	,[md_InsertedBy]		
	,[md_ChangedTime]	
	,[md_ChangedBy]		
	,[md_RowVersion]		
	,[md_RowState]		
	,[md_SourceId]		
	,[md_StgRowId]		
	,[md_LoadJobId]		
	,[md_DqLevel]			
	,[md_DqIssueDescription]	
	,[md_BPK]				
	,[md_BD]			

FROM [CoreData].[Employment];
GO
