/*
================================================================= 

View name:	[CoreX].[Employee]

Purpose:	Employee master data 

Content:	Current employment including Manager category

Sensitive:	Restricted - Contains personal information. May be shared within Sweco.

Hints:		

 

================================================================= 

Changes:  2021-09-14	SEMBOD	Use swecoaccess.dbo.view_roleAssignmentsActiveUnits as Mgr
		  2021-10-07	SEARNO	Added info about the employee's manager and limited "directreports" to active only
		  2021-10-11	SEMBOD	Added work calendar, future change, office, function. Changed sources to CoreData tables
		  2021-10-26	SEMBOD	Added md columns
		  2021-11-02	SECKRA	Changed the name on EmpPricingCategoryId to EmployeePricingCategoryId and EmpPricingCategoryName to EmployeePricingCategoryName
		  2021-11-22	SEMLJS	Added AND eea.[Key] = 'Email' to join with CoreData.EmployeeEmailAddress
		  2021-11-23	SEARNO	Added JobClassification columns. Changed SeniorityDate to SeniorityHireDate.
		  2021-12-28	SEARNO	Added column ExistsInAD for CV partner
		  2022-01-02	SEARNO	Added column Show to enable filtering out persons to be hidden from Insight/Contact/O365 address book etc
		  2022-01-14	SEMBOD	Removed EmpRegularWorkWeek
		  2022-01-18	SEARNO	Deviating manager exposed if set. Replaced joins on v1 views.
		  2022-01-19	SEGUNJ	Disabled Gender
		  2022-01-24	SEARNO	Users with no account get show = 0 (previously 1)
		  2022-01-24	SEARNO	Filtered out nonactive employes from direct reports
		  2022-01-24	SEARNO	Employment, company and team become mandatory
		  2022-01-25	SEARNO	Direct reports must take systenon/offboarding dates into consideration
		  2022-02-02	SEARNO	Dropped deprecated column Gender		  
		  2022-02-21	SEGUNJ	Added DirectPhone, MobilePhone and EstablishmentNo coulmns.
		  2022-02-25	SEMLJS	Switched to [CoreX].[EmployeeAccess] from [swecoaccess].[dbo].[view_roleAssignmentsActiveUnits]
		  2022-03-18	SEMBOD	Added OfficeCountryId + Corrected dates LegalTeam dates and OperatingTeam dates
		  2022-05-19	SEARNO	Added columns for non-deviating ("line") manager and flag for separation
		  2022-07-11	SEMLJS	Only display deviating manager if source is SF
		  2022-07-22	SEARNO	Fill jobfunction & jobclassification from old structure when new values are not available
		  2022-08-19	SEARNO	Expose default preferred language based on company country instead of only languages specified in local HR
		  2022-10-27	SEARNO	Add columns departmentid, businessunitid, divisionid, businessareaid
		  2023-01-31	SEMLJS	Changed from GETDATE() to DATEADD(dd, 0, DATEDIFF(dd, 0, GETDATE())) in logic for IsActive to include WorkEndDate (ISNULL(e.SystemOffBoardingDate, Employment.TerminationDate))
		  2023-10-16	SEMBOD	Added IsEUEmployed
		  2025-03-26	SEVEWP	Added handling for duplicate future changes on employment and legal team
================================================================= 

*/
CREATE   VIEW [CoreX].[Employee] AS
SELECT
-- Name, identity, organisation
		e.Domain + '\' + e.Login									AS bk_Employee,
		e.Domain,
		e.Login,
		ISNULL(e.PreferredFirstName, e.FirstName) as Firstname,
		e.Lastname,
		ISNULL(e.PreferredFirstName, e.FirstName) + ' ' + e.Lastname FullName,
		ISNULL(e.[DisplayName], (e.[LastName]+','+' '+ISNULL(e.[PreferredFirstName],e.[FirstName]))) AS [DisplayName],
		eea.Value													AS Email,
		e.BirthDate	,
		LegalTeam.CompanyId,
		LegalTeam.TeamId,
		ed.ValidFromDate											AS LegalTeamValidFromDate,
		ed.ValidToDate												AS LegalTeamValidToDate,
		OperatingTeam.CompanyId										AS OperatingCompanyId,
		OperatingTeam.TeamId										AS OperatingTeamId,
		eod.ValidFromDate											AS OperatingTeamValidFromDate,
		eod.ValidToDate												AS OperatingTeamValidToDate,
		LegalTeam.DepartmentId,
		LegalTeam.BusinessUnitId,
		LegalTeam.DivisionId,
		LegalTeam.BusinessAreaId,

-- Office
		e.OfficeAddressKey											AS OfficeAddressKey,
		loa.EstablishmentNo											AS OfficeEstablishmentNo,
		loa.Street													AS OfficeAddressStreet,
		loa.Street2													AS OfficeAddressStreet2,
		loa.City													AS OfficeAddressCity,
		loa.ZipCode													AS OfficeAddressZipCode,
		OfficeCountry.CountryKey									AS OfficeCountryId,
		OfficeCountry.CountryName									AS OfficeCountryName,

-- Info about the employee's manager
		em2.Domain + '\' + em2.Login as bk_EmployeeManager,				-- Ex: LoginId
		em2.Domain as ManagerDomain,
		em2.Login as ManagerLogin,
		ISNULL(em2.PreferredFirstName, em2.FirstName) as ManagerFirstname,
		em2.Lastname as ManagerLastName,
		em2.Firstname + ' ' + em2.Lastname as ManagerFullName,
		CASE WHEN em2.Login <> em2_nondev.Login THEN 1 ELSE 0 END AS MangerIsIndividuallySet, 
		CASE WHEN em2.Login <> em2_nondev.Login THEN em2_nondev.Domain + '\' + em2_nondev.Login	ELSE NULL END AS bk_EmployeeLineManager,				
		CASE WHEN em2.Login <> em2_nondev.Login THEN em2_nondev.Domain						ELSE NULL END AS LineManagerDomain,
		CASE WHEN em2.Login <> em2_nondev.Login THEN em2_nondev.Login						ELSE NULL END AS LineManagerLogin,
		CASE WHEN em2.Login <> em2_nondev.Login THEN ISNULL(em2_nondev.PreferredFirstName, em2_nondev.FirstName) ELSE NULL END AS LineManagerFirstname,
		CASE WHEN em2.Login <> em2_nondev.Login THEN em2_nondev.Lastname					ELSE NULL END AS LineManagerLastName,
		CASE WHEN em2.Login <> em2_nondev.Login THEN em2_nondev.Firstname + ' ' + em2_nondev.Lastname ELSE NULL END AS LineManagerFullName,

-- Dates, type, status, subconsultancy
		e.SeniorityHireDate,									--AS SeniorityDate,
		--e.SystemOnBoardingDate,									--as WorkStartDate, 
		--e.SystemOffBoardingDate,								--as WorkEndDate,		
		--e.Active as IsActive,
		ISNULL(e.SystemOnBoardingDate, Employment.HireDate)				AS WorkStartDate,						
		ISNULL(e.SystemOffBoardingDate, Employment.TerminationDate)		AS WorkEndDate,					
		CASE WHEN DATEADD(dd, 0, DATEDIFF(dd, 0, GETDATE())) BETWEEN ISNULL(e.SystemOnBoardingDate, Employment.HireDate) AND COALESCE(e.SystemOffBoardingDate, Employment.TerminationDate, '2099-12-31') THEN 1 ELSE 0 END AS IsActive,
		let.EmploymentContractTypeId						AS EmploymentContractTypeId,						-- Ex: EmployeeTypeId
		let.EmploymentContractTypeName						AS EmploymentContractTypeName,
		ecst.EmploymentContractSubTypeId,
		ecst.EmploymentContractSubTypeName,
		sc.PayTypeId AS PayTypeId,										-- Ex: PayType
		-- PayTypeName,
		ISNULL(ew.WorkRatio,0) WorkRatio,
		ew.ValidFromDate									AS WorkRatioValidFromDate,
		ew.ValidToDate										AS WorkRatioValidToDate,
		Employment.src_ChangedTime  AS CompanyChangedDate,
			--ec.[Changed] CompanyChangedDate,							-- Ex: Changed
		euat.UserAccountTypeId								AS EmployeeUserAccountTypeId,	
		euat.UserAccountTypeName							AS EmployeeUserAccountTypeName,
		CASE WHEN LEFT(euat.UserAccountTypeName,2)='AD' THEN 1 ELSE 0 END AS ExistsInAD,
		CASE WHEN PATINDEX('%Hide%', ISNULL(euat.UserAccountTypeName,'Hide')) = 0 THEN 1 ELSE 0 END AS Show,
		EmpStatus.[StatusId]								AS EmploymentStatusId,	
		EmpStatus.[StatusName]								AS EmploymentStatusName,
		Employment.ValidFromDate							AS EmploymentValidFromDate,
		Employment.ValidToDate								AS EmploymentValidToDate,
		ISNULL(ejf.JobFunctionId, ejc_legacy.CategoryFunctionLocalId) AS JobFunctionId,				-- Added ISNULL and legacy filler when new jobfunction & jobclassification structure is not filled / Arnold 2022-07-22
		ISNULL(ejf.JobFunctionName, ejc_legacy.CategoryFunctionLocalName) AS JobFunctionName, 
		ISNULL(ejc.JobClassificationId, ejc_legacy.SubCategoryFunctionLocalId) AS JobClassificationId,
		ISNULL(ejc.JobClassificationName, ejc_legacy.SubCategoryFunctionLocalName) AS JobClassificationName,
		ISNULL(SelectedLanguage.LangKey, DefaultLanguage.LangKey) AS  PreferredLanguageId,					-- changed from langid
		ISNULL(SelectedLanguage.LanguageName, DefaultLanguage.LanguageName) AS PreferredLanguageName,
		ee.VendorByCompanyKey as VendorKey,									
		c.CompanyGroupId as SwecoGroupId,
		
-- extended info
		epc.EmployeePricingCategoryId							AS EmployeePricingCategoryId,		-- Changed column name from EmpPricingCategoryId to EmployeePricingCategoryId
		epc.EmployeePricingCategoryName							AS EmployeePricingCategoryName,		-- Changed column name from EmpPricingCategoryName to EmployeePricingCategoryName
		eel.EducationLevelId,
		eel.EducationLevelName,
		e.PayrollEmployeeId,
		e.LegacyDomain,
		e.LegacyLogin,
		e.GraduationYear,
		e.CommutingDistanceKm,
		e.EducationalFund,
		e.Title												AS ADTitle,
		epnd.value											AS	DirectPhone,
		epnm.value											AS	MobilePhone,
		CompanyCountry.EU									AS	IsEUEmployed,
		
-- Info about the employee's own role as manager

		CASE WHEN mgr.UnitLevelId IS NULL THEN 0 ELSE 1 END as IsManager,
		ISNULL(Reports.DirectReports,0) as DirectReports,
		emc.ManagerCategoryId,
		emc.ManagerCategoryName,
		u.UnitLevelId as ManagerCategoryLevelId,
		u.UnitLevelName as ManagerCategoryLevelName,

-- changes
		CAST(CASE WHEN efc.EmployeeKey IS NULL THEN 0 ELSE 1 END AS bit)	AS FutureEmployment,
		CAST(CASE WHEN eltfc.EmployeeKey IS NULL THEN 0 ELSE 1 END AS bit)	AS FutureTeamChange,

		futEmpMan.Domain + '\' + futEmpMan.[Login] as bk_FutureEmployeeManager,				
		futEmpMan.Domain as FutureManagerDomain,
		futEmpMan.Login as FutureManagerLogin,
		ISNULL(futEmpMan.PreferredFirstName, futEmpMan.FirstName) as FutureManagerFirstname,
		futEmpMan.Lastname as FutureManagerLastName,
		futEmpMan.Firstname + ' ' + futEmpMan.Lastname as FutureManagerFullName,
		
-- meta data
		e.[src_ChangedBy]													AS [src_ChangedBy], 
		e.[src_ChangedTime]													AS [src_ChangedTime], 
		e.[md_InsertedTime]													AS [md_InsertedTime], 
		e.[md_InsertedBy]													AS [md_InsertedBy], 
		e.[md_ChangedTime]													AS [md_ChangedTime], 
		e.[md_ChangedBy]													AS [md_ChangedBy], 
		e.[md_RowVersion]													AS [md_RowVersion], 
		e.[md_RowState]														AS [md_RowState], 
		e.[md_SourceId]														AS [md_SourceId], 
		e.[md_StgRowId]														AS [md_StgRowId], 
		e.[md_LoadJobId]													AS [md_LoadJobId], 
		e.[md_DqLevel]														AS [md_DqLevel], 
		e.[md_DqIssueDescription]											AS [md_DqIssueDescription], 
		e.[md_BD]															AS [md_BD],
		e.[md_BPK]															AS [md_BPK],
		e.EmployeeKey														AS EmployeeKey
		
FROM CoreData.Employee e
JOIN Core.Employment						AS Employment		ON e.EmployeeKey = Employment.EmployeeKey
JOIN CoreData.OrgCompany					AS c				ON Employment.CompanyId = c.CompanyId 
JOIN CoreData.EmployeeLegalTeam				AS ed				ON e.EmployeeKey = ed.EmployeeKey 
JOIN CoreData.OrgTeam						AS LegalTeam		ON ed.TeamKey = LegalTeam.TeamKey
LEFT JOIN CoreData.EmployeeOperatingTeam	AS eod				ON e.EmployeeKey = eod.EmployeeKey and GETDATE() between eod.ValidFromDate and isnull(eod.ValidToDate,'2099-12-31')
LEFT JOIN CoreData.OrgTeam					AS OperatingTeam	ON eod.TeamKey = OperatingTeam.TeamKey

LEFT JOIN CoreData.EmployeeWorkRatio		AS ew				ON e.EmployeeKey = ew.EmployeeKey 
LEFT JOIN CoreData.EmployeeVendor			AS ee				ON e.EmployeeKey = ee.EmployeeKey
LEFT JOIN CoreData.EmployeePersonal			AS ep				ON e.EmployeeKey = ep.EmployeeKey
LEFT JOIN CoreData.EmpPayType				AS sc				ON sc.PayTypeKey = ep.PayTypeKey 
LEFT JOIN 
(
	SELECT ea.EmployeeKey, MIN(UnitLevelId) AS UnitLevelId 
	FROM [CoreX].[EmployeeAccess] ea 
	WHERE AccessRoleKey IN (4,29) AND IsActiveUnit = 1 
	GROUP BY ea.EmployeeKey
) AS Mgr ON e.EmployeeKey = mgr.EmployeeKey

LEFT JOIN CoreData.EmpManagerCategory		AS emc				ON emc.UnitLevelKey = mgr.unitLevelId 
LEFT JOIN CoreData.OrgUnitLevel				AS U				ON U.UnitLevelKey = emc.UnitLevelKey 
LEFT JOIN 
(
	SELECT ManagerKey, COUNT(*) DirectReports 
	FROM [CoreData].[EmployeeManager] EM 
	JOIN CoreData.Employment Empl ON Empl.EmployeeKey = EM.EmployeeKey 
	JOIN CoreData.Employee E ON E.EmployeeKey = EM.EmployeeKey 
	WHERE GETDATE() BETWEEN ISNULL(E.SystemOnBoardingDate, Empl.ValidFromDate) AND COALESCE(E.SystemOffBoardingDate, Empl.ValidToDate, '2099-12-31') 
	GROUP BY ManagerKey
	) AS Reports ON ManagerKey = e.EmployeeKey 

LEFT JOIN coredata.EmploymentContractType	AS let				ON let.EmploymentContractTypeKey = Employment.EmploymentContractTypeKey 
LEFT JOIN CoreData.EmployeeEmailAddress		AS eea				ON e.EmployeeKey = eea.EmployeeKey AND eea.[Key] = 'Email'
LEFT JOIN CoreData.Employee_UserAccountType	AS e_uat			ON e.EmployeeKey = e_uat.EmployeeKey
LEFT JOIN CoreData.EmpUserAccountType		AS euat				ON euat.UserAccountTypeKey = e_uat.EmployeeUserAccountTypeKey
LEFT JOIN CoreData.EmpStatus									ON Employment.StatusKey =  EmpStatus.StatusKey
LEFT JOIN CoreData.EmployeeManager			AS em1				ON em1.EmployeeKey = e.EmployeeKey
LEFT JOIN CoreData.EmployeeDeviatingManager	AS edm1				ON edm1.EmployeeKey = e.EmployeeKey AND edm1.md_SourceId = 331
LEFT JOIN CoreData.Employee					AS em2				ON em2.EmployeeKey = ISNULL(edm1.ManagerKey,em1.ManagerKey)
LEFT JOIN CoreData.Employee					AS em2_nondev		ON em2_nondev.EmployeeKey = em1.ManagerKey
LEFT JOIN CoreData.Employee					AS futEmpMan		ON futEmpMan.EmployeeKey = em1.FutureManagerKey

LEFT JOIN 
(
	SELECT *, ROW_NUMBER() OVER (PARTITION BY EmployeeKey ORDER BY HireDate ASC) AS RowNo
	FROM CoreData.EmploymentFutureChanges		
)AS efc ON e.EmployeeKey = efc.EmployeeKey AND efc.RowNo = 1

LEFT JOIN 
(
	SELECT *, ROW_NUMBER() OVER (PARTITION BY EmployeeKey ORDER BY ValidFromDate ASC) AS RowNo
	FROM CoreData.EmployeeLegalTeamFutureChanges
)AS eltfc ON e.EmployeeKey = eltfc.EmployeeKey AND eltfc.RowNo = 1

LEFT JOIN CoreData.LocOfficeAddress			AS loa				ON e.OfficeAddressKey = loa.AddressKey
LEFT JOIN CoreData.LocCountry				AS OfficeCountry	ON loa.CountryKey = OfficeCountry.CountryKey
LEFT JOIN CoreData.LocCountry				AS CompanyCountry	ON c.CountryId = CompanyCountry.CountryKey		-- For default language, 2022-08-19

LEFT JOIN CoreData.LangLanguage				AS SelectedLanguage	ON e.EmployeePreferredLanguageKey = SelectedLanguage.LangKey	and SelectedLanguage.LanguageKey = 13
LEFT JOIN CoreData.LangLanguage				AS DefaultLanguage	ON CompanyCountry.CountryLanguageKey =	DefaultLanguage.LangKey		and DefaultLanguage.LanguageKey = 13

LEFT JOIN CoreData.EmpJobClassification		AS ejc				ON ejc.JobClassificationKey = e.JobClassificationKey
LEFT JOIN CoreData.EmpJobFunction			AS ejf				ON ejc.JobFunctionKey = ejf.JobFunctionKey
LEFT JOIN dbo.v2EmployeeFunction			AS ejc_legacy		ON ejc_legacy.EmployeeId = e.EmployeeKey 
LEFT JOIN CoreData.EmploymentContractSubType AS ecst			ON Employment.EmploymentContractSubTypeKey = ecst.EmploymentContractSubTypeKey

-- extended info
LEFT JOIN [CoreData].[EmpPricingCategory]	AS epc				ON e.EmployeePricingCategoryKey = epc.EmployeePricingCategoryKey
LEFT JOIN [CoreData].[EmpEducationLevel]	AS eel				ON e.EducationLevelKey = eel.EducationLevelKey
LEFT JOIN CoreData.EmployeePhoneNumber		AS epnd				ON e.EmployeeKey = epnd.EmployeeKey AND epnd.[Key] = 'DirectPhone'
LEFT JOIN CoreData.EmployeePhoneNumber		AS epnm				ON e.EmployeeKey = epnm.EmployeeKey AND epnm.[Key] = 'MobilePhone'
GO
