/****** Object:  View [CoreEcoX].[EcoTimeRow]    Script Date: 2025-07-16 15:57:21 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


/* 

================================================================= 

View name:	[CoreEcoX].[EcoTimeRow]

Purpose:	All approved time registrations.

Content:	Timerow data like activity, task, employee, project, week, day, GL month, hours, revenue and cost. also basic employee and project masterdata.

Sensitive:	Restricted - Contains personal and financial information. May be shared according to DoA and project permissions.

Hints:		Revenue is total revenue for the line. Divide by Hours to get value per hour.
			BaseCost is total basecost (overhead not included) for the line. Divide by Hours to get value per hour.
			OverheadCost means overhead. BaseCost + OverheadCost = Full cost.
			If possible, limit select queries on timefiscalmonth, for best performance.
			Note that EmployeeType (and all other masterdata) shows the present values, not the historical values from the time of the transaction.
			Be careful to filter on the employee's or project's organisation according to perspective.
			Use rbk-columns as join key against project and organisation views' bk-columns.
 

================================================================= 

Changes:  
			2021-07-07	SEARNO	Switched to Core5.x versions of activity and timecode ref tables
			2022-02-14	SEARNO	Core 5.3: Join on core.LocCountry and Core.Employee instead of dbo. Change output column names [EmploymentType...] to [EmploymentContractType...].
			2022-12-21	SEARNO	Change from tr.ProjectCompanyId to p.CompanyId to expose new companynumber after conversion
================================================================= 

SELECT TOP 10 * FROM [CoreEcoX].[EcoTimeRow]

*/ 

CREATE   VIEW [CoreEcoX].[EcoTimeRow]

AS

	SELECT 
		tr.[EmployeeCompanyId]																										AS [EmployeeCompanyId],
		ec.CompanyName																												AS [EmployeeCompanyName],
		ot.TeamId																													AS [EmployeeTeamId],
		CAST(pot.[CompanyId] as varchar)+'/'+ot.[TeamId]																			AS [rbk_EmployeeTeam],			
		ot.TeamName																													AS [EmployeeTeamName], 
		e.Domain																													AS [EmployeeDomain],
		e.Login																														AS [EmployeeLogin], 
		e.[Domain]+'/'+e.[Login]																									AS [EmployeeLoginId],
		ISNULL(e.PreferredFirstName,e.Firstname)																					AS [EmployeeFirstName],
		e.LastName																													AS [EmployeeLastName], 
		e.FirstNameLastName																											AS [EmployeeFullName],
		tr.EmployeeTypeID																											AS EmploymentContractTypeId,
		ect.EmploymentContractTypeName																								AS [EmploymentContractTypeName], 
		p.[CompanyId]																												AS [ProjectCompanyId],
		pc.[CompanyName]																											AS [ProjectCompanyName],
		p.[CompanyId] +'/'+p.[ProjectNo]																							AS [rbk_Project],
		p.ProjectNo																													AS [ProjectId],				
		p.ProjectName																												AS [ProjectName], 
		pt.[ProjectTaskCode]																										AS [ProjectTaskId],			
		pt.ProjectTaskName																											AS [ProjectTaskName], 
		pot.[CompanyId]+'/'+pot.[TeamId]																							AS [rbk_ProjectTeam],
		pot.TeamId																													AS [ProjectTeamId],
		pot.TeamName																												AS [ProjectTeamName], 
		a.ActivityNumber																											AS [ActivityId],					-- Number/Id?
		a.ActivityName																												AS [ActivityName], 
		tr.[OvertimeCode]																											AS [OvertimeId],
		tc.[TimecodeID]																												AS [TimecodeId],
		tc.TimeCodeName																												AS [TimecodeName],
		tc.IncludedinFTE																											AS [FTEflag], 
		tr.[TimeDate]																												AS [TimeDate], 
		tr.[TimeWeek]																												AS [TimeWeek], 
		tr.TimeFiscalMonth																											AS [FiscalMonth], 
		tr.[Hours]																													AS [Hours], 
		tr.Price																													AS [SalesPrice], 
		pcurr.CurrencyCode																											AS [SalesPriceCurrency],
		tr.Cost																														AS [BaseCost], 
		tr.OH																														AS [OverheadCost], 
		ecurr.CurrencyCode																											AS [CostCurrency],
		evt.ValueTypeId																												AS [ValueTypeId],
		evt.ValueTypeName																											AS [ValueTypeName], 
		tr.[InstanceKey]																											AS [InstanceKey],
		tr.[src_ChangedTime]																										AS [src_ChangedTime], 
		tr.[md_InsertedTime] 																										AS [md_InsertedTime], 
		tr.[md_InsertedBy]																											AS [md_InsertedBy], 
		tr.[md_ChangedTime]																											AS [md_ChangedTime], 
		tr.[md_ChangedBy] 																											AS [md_ChangedBy], 
		tr.[md_RowVersion]	 																										AS [md_RowVersion], 
		tr.[md_RowState] 																											AS [md_RowState], 
		tr.[md_SourceId] 																											AS [md_SourceId], 
		tr.[md_StgRowId] 																											AS [md_StgRowId], 
		tr.[md_LoadJobId] 																											AS [md_LoadJobId], 
		tr.[md_DqLevel] 																											AS [md_DqLevel], 
		tr.[md_DqIssueDescription]																									AS [md_DqIssueDescription],
		tr.[md_BD]																													AS [md_BD],
		tr.[md_BPK]																													AS [md_BPK],
		tr.TimeRowKey																												AS [EcoTimeRowKey]
	FROM CoreData.EcoTimeRow				tr
	LEFT JOIN CoreData.OrgCompany			ec	ON tr.EmployeeCompanyId = ec.CompanyId
	LEFT JOIN CoreData.OrgCompany			pc	ON tr.ProjectCompanyId = pc.CompanyId
	LEFT JOIN CoreData.Employee				e	ON tr.EmployeeKey = e.EmployeeKey
	LEFT JOIN CoreData.ProjectTask			pt	ON tr.ProjectTaskKey = pt.ProjectTaskKey
	LEFT JOIN CoreData.Project				p	ON pt.ProjectKey = p.ProjectKey
	LEFT JOIN CoreData.OrgTeam				pot	ON tr.ProjectTeamKey = pot.TeamKey
	LEFT JOIN CoreData.Activity					a	ON tr.ActivityNumber = a.ActivityNumber
	LEFT JOIN Core.EcoTimecode				tc	ON tc.TimecodeID = tr.SwecoTimecodeId
	LEFT JOIN CoreData.EcoValueType			evt	ON evt.ValueTypeId = tr.ValueTypeKey 
	LEFT JOIN CoreData.OrgTeam				ot	ON tr.EmployeeTeamKey = ot.TeamKey 
	LEFT JOIN CoreData.EcoCurrency			ecurr	ON ecurr.CurrencyKey = ec.CurrencyKey
	LEFT JOIN CoreData.EcoCurrency			pcurr	ON pcurr.CurrencyKey = pc.CurrencyKey
	LEFT JOIN CoreData.EmploymentContractType ect	ON tr.EmployeeTypeId = ect.EmploymentContractTypeKey

GO
