CREATE VIEW [Core].[OrganisationAllLevels]
AS
SELECT --DISTINCT 
		5 as UnitLevelId,
		CAST('Team' AS VARCHAR(30)) as UnitLevelName,
		BusinessAreaID, 
		isnull(DivisionID, '') as DivisionID, 
		isnull(BusinessUnitID, '') as BusinessUnitID, 
		isnull(DepartmentID, '') as DepartmentID, 
		TeamId, 
		CompanyID, 
		TeamId as Id,
		TeamKey AS UnitKey,		-- New attribute Pier_20220225
		CompanyId as ParentId, 
		TeamName AS Name, 
		[OrgUnitId],
		[Active],
		ValidFromDate, 
		ValidToDate,
		[TeamBudgetTypeKey],  
		[FMteamOfficeKey],     
		[MgmtTeamUnitLevelKey]
FROM [Core].[OrgTeam]
--ORDER BY 2,3,4,5,6

UNION

SELECT --DISTINCT 
        4 as UnitLevelId, 
        CAST('Department' AS VARCHAR(30)) as UnitLevelName,
        BusinessAreaID, 
        isnull(DivisionID, '') as DivisionID, 
        isnull(BusinessUnitID, '') as BusinessUnitID, 
        isnull(DepartmentID, '') as DepartmentID, 
        '' as TeamId, 
        '' as CompanyID, 
        DepartmentId as Id, 
        DepartmentKey AS UnitKey,		-- New attribute Pier_20220225
		BusinessAreaId as ParentId, 
        DepartmentName AS Name, 
        [OrgUnitId],
        [Active],
        ValidFromDate, 
        ValidToDate,
		'' as [TeamBudgetTypeKey],  
		NULL as [FMteamOfficeKey],     
		NULL as [MgmtTeamUnitLevelKey]
FROM [Core].[OrgDepartment]
--ORDER BY 2,3,4,5,6

UNION

SELECT --DISTINCT 
        3 as UnitLevelId, 
        CAST('BusinessUnit' AS VARCHAR(30)),
        BusinessAreaID, 
        isnull(DivisionID, '') as DivisionID, 
        isnull(BusinessUnitID, '') as BusinessUnitID, 
        '' as DepartmentID, 
        '' as TeamId, 
        '' as CompanyID, 
        BusinessUnitID as Id, 
		BusinessUnitKey AS UnitKey,		-- New attribute Pier_20220225
        BusinessAreaId as ParentId, 
        BusinessUnitName AS Name, 
        [OrgUnitId],
        [Active],
        ValidFromDate, 
        ValidToDate,
		'' as [TeamBudgetTypeKey],  
		NULL as [FMteamOfficeKey],     
		NULL as [MgmtTeamUnitLevelKey]
FROM [Core].[OrgBusinessUnit]
--ORDER BY 2,3,4,5,6

UNION

SELECT --DISTINCT 
        2 as UnitLevelId,
        CAST('Division' AS VARCHAR(30)),
        BusinessAreaID, 
        isnull(DivisionID, '') as DivisionID, 
        '' as BusinessUnitID, 
        '' as DepartmentID, 
        '' as TeamId, 
        '' as CompanyID, 
        DivisionID as Id, 
		DivisionKey AS UnitKey,		-- New attribute Pier_20220225
        BusinessAreaId as ParentId, 
        DivisionName AS Name, 
        [OrgUnitId],
        [Active],
        ValidFromDate, 
        ValidToDate,
		'' as [TeamBudgetTypeKey],  
		NULL as [FMteamOfficeKey],     
		NULL as [MgmtTeamUnitLevelKey]
FROM [Core].[OrgDivision]
--ORDER BY 2,3,4,5,6

UNION

SELECT --DISTINCT 
        1 as UnitLevelId,
        CAST('Business Area' AS VARCHAR(30)),
        BusinessAreaID, 
        '' as DivisionID, 
        '' as BusinessUnitID, 
        '' as DepartmentID, 
        '' as TeamId, 
        '' as CompanyID, 
        BusinessAreaID as Id, 
		BusinessAreaKey AS UnitKey,		-- New attribute Pier_20220225
        '' as ParentId, 
        BusinessAreaName AS Name, 
        [OrgUnitId],
        [Active],
        ValidFromDate, 
        ValidToDate,
		'' as [TeamBudgetTypeKey],  
		NULL as [FMteamOfficeKey],     
		NULL as [MgmtTeamUnitLevelKey]
FROM [Core].[OrgBusinessArea]
--ORDER BY 2,3,4,5,6

UNION

SELECT --DISTINCT 
		99 as UnitLevelId,
		CAST('Company' AS VARCHAR(30)),
		'' as BusinessAreaID, 
		'' as BusinessDivisionID, 
		'' as BusinessUnitID, 
		'' as DepartmentId, 
		'' as TeamId, CompanyID, 
		CompanyId as Id,  
		CompanyKey AS UnitKey,		-- New attribute Pier_20220225
		'' as ParentId,
		CompanyName as Name,
		[OrgUnitId],
		[Active],
		ValidFromDate, 
		ValidToDate,
		'' as [TeamBudgetTypeKey],  
		NULL as [FMteamOfficeKey],     
		NULL as [MgmtTeamUnitLevelKey]
FROM [Core].[OrgCompany]
--ORDER BY 2,3,4,5,6

UNION

SELECT -- Company Group
        0 as UnitLevelId,
        CAST('Company Group' AS VARCHAR(30)),
        '0' as BusinessAreaID, 
        '' as BusinessDivisionID, 
        '' as BusinessUnitID, 
        '' as DepartmentId, 
        '' as TeamId, 
        '' as CompanyID, 
        '0' as Id,  
        0 AS UnitKey,		-- New attribute Pier_20220225 
        '0' as ParentId,
        'Group' as Name, 
        '0-0' as [OrgUnitId],
        1 as Active,  
        '19000101', 
        '21991231',
		'' as [TeamBudgetTypeKey],  
		NULL as [FMteamOfficeKey],     
		NULL as [MgmtTeamUnitLevelKey]

--ORDER BY [OrgUnitId]
GO
