/****** Object:  View [Core].[Project]    Script Date: 2025-07-16 15:57:21 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


/*
	20210428	-	Added [InitiatingOpportunityKey], [BidClosedDate], [src_CreatedDate] / SECKRA

	ChangeTime: 2021-04-09
	ChangeBy: sepika
	Change: Added the new rename column ProjectCurrency

	Project.Currency is the currency specified in the Project Contract
	It will be the currency used for Customer Invoicing the Customer in the Project.

	In Maconomy, the GL Transactions will store the amount in the CompanyCurrency (using Exchange Rate) as Accounting is based on CompanyCurrency.
	GL Transaction will also store an attribute with the InvoicedAmount which is in InvoicedCurrency (=Project ContractCurrency).

	2022-12-02	SEVEWP	Moved BidProbability to CoreEco
	2023-05-15	SEMLJS	Added ProjectClosureRequested
	2024-10-17	SEWAAH	Added security level table ( need to be rewritten after cofidential flag is phased out)

*/
CREATE VIEW [Core].[Project]

AS

	SELECT
		 A.[ProjectKey]
		,A.[CompanyId]
		,A.[ProjectNo]
		,A.[ProjectName]
		,A.[ProjectLevel]
		,A.[ProjectDescription]
		,A.[MainProjectKey]
		,A.[ProjectParentKey]
		,A.[ProjectTypeKey]
		,A.[ProjectStatusKey]
		,A.[ProjectContractTypeKey]
		,A.[MunicipalityKey]
		,A.[TeamKey]
		,A.[ProjectStartDate]
		,A.[ProjectEndDate]
		,A.[CompanyProjectNo]
		,A.[IsOpportunity]
		,A.[IsBid]
		,A.[IsTender]		-- To be retired, is replaced by IsBid
		,A.[IsExternal]
		,A.[IsMainProject]
		,A.[Active]
		,A.[CustomerContact]
		,A.[CustomerContactEmail]
		,A.[CustomerReference]
		,A.[InitiatingOpportunityKey]					-- Added 20210428  /seckra
		,A.[InitiatingBidKey]							-- Added 20210616  /searno
		,A.[TenderId]									-- To be retired
		,A.[Archived]
		--,A.[Confidential]		
		,COALESCE(sl.SecurityLevelCode,A.[Confidential])	as 	[Confidential]
		,A.[Secure]
		,A.[RestrictedReporting]
		,A.[AllowExpenses]
		,A.[AllowNonBillableExpenses]
		,A.[CurrencyKey]						
		,A.[ProjectInsuranceNo]
		,A.[ProjectRiskProfileKey]	
		,A.[ProjectRiskLevelKey]	 --- ?
		,A.[BidTypeKey]					
		,A.[BidSubmissionDate]
		,A.[BidStartDate]				
		,A.[BidEndDate]				
		,A.[BidClosedDate]								-- Added 20210428  /seckra
		,A.[ProjectStageOutcomeKey]	
		,A.[ProjectStartDateEstimated]
		,A.[ProjectEndDateEstimated]			
		,A.[AccessLevelName]
		,A.[SmallProject]
		,A.[ProjectClosureRequested]
		,A.[src_CreatedDate]							-- Added 20210428  /seckra 
		,A.[src_ChangedBy]
		,A.[src_ChangedTime]
		,A.[md_InsertedTime]
		,A.[md_InsertedBy]
		,A.[md_ChangedTime]
		,A.[md_ChangedBy]
		,A.[md_RowVersion]
		,A.[md_RowState]
		,A.[md_SourceId]
		,A.[md_StgRowId]
		,A.[md_LoadJobId]
		,A.[md_DqLevel]
		,A.[md_DqIssueDescription]
		,A.[md_BPK]
		,A.[md_BD]
	FROM [CoreData].[Project] A
	LEFT JOIN CoreData.ProjectSecurityLevel psl ON psl.ProjectKey = A.ProjectKey
	LEFT JOIN CoreData.SecurityLevel sl ON sl.SecurityLevelKey = psl.SecurityLevelKey

GO
