/****** Object:  View [CoreEcoX].[EcoTransaction]    Script Date: 2025-07-16 15:57:21 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/*

================================================================= 

View name:	[CoreEcoX].[EcoTransaction]


Purpose:	All GL entries, imported from Maconomy. 

Content:	Transaction data like account, team, activity, task, employee, project, finance entry date, hours and financial values. Also basic employee and project masterdata.

Sensitive:	Restricted - Contains personal and financial information. May be shared according to DoA and project permissions.

Hints:		[Count] column contains hours. 
			Note that ProjectTeam, EmployeeType and all other masterdata shows the present values, not the historical values from the time of the transaction.
			Filter on valuetypeid = 3 to get actuals, valuetypeid = 6 to get project budget.
			InterCompanyId is used for legal group reconciliations and includes partly different data than the counterpart organisation.
			For PnL type reports, multiply the hours by [HoursSign_for_PnL] if [Apply_HoursSign_for_PnL]. Multiply the amount by [ProjCostSign_for_PnL] if [Apply_ProjCostSign_for_PnL].
			For project type reports, multiply the amount by [RevenueSign_for_ProjectReports] if [Apply_RevenueSign_for_ProjectReports].
			If possible, limit select queries on transactiondate, for best performance.
			Use rbk-columns as join key against project and organisation views' bk-columns.

================================================================= 

Changes:  
			2021-09-11	SEARNO	Adding column for Transactiontype
			2022-02-15	SEARNO	Core5 upgrade. Employee and accuont ref data from CoreData instead of Dbo. 
		
================================================================= 

SELECT TOP 10 * FROM [CoreEcoX].[EcoTransaction]

*/
CREATE   VIEW [CoreEcoX].[EcoTransaction]
AS
SELECT
tr.CompanyId																		AS [CompanyId],
c.CompanyName																		AS [CompanyName], 

t.[CompanyId]+'/'+t.[TeamId]														AS [rbk_Team],
t.TeamId																			AS [TeamId],
t.TeamName																			AS [TeamName], 
tr.TransactionDate																	AS [TransactionDate], 
tt.TransactionTypeId																AS [TransactionTypeId],
tt.TransactionTypeName																AS [TransactionTypeName],
tr.VoucherId																		AS [VoucherId], 
ma.DisplayAccountId																	AS [MainAccountId],
ma.MainAccountName																	AS [MainAccountName],
a.AccountID																			AS [AccountId],
a.AccountName																		AS [AccountName], 
pc.CompanyId																		AS [ProjectCompanyId],
pc.CompanyName																		AS [ProjectCompanyName],

pc.CompanyId+'/'+pt.TeamId															AS [rbk_ProjectTeam],			-- new rbk
pt.TeamId																			AS [ProjectTeamId],
pt.TeamName																			AS [ProjectTeamName], 

p.CompanyId+'/'+p.ProjectNo															AS [rbk_Project],				-- New rbk
p.ProjectNo																			AS [ProjectId],
p.ProjectName																		AS [ProjectName],

p.[CompanyId]+'/'+p.[ProjectNo]+'/'+pta.[ProjectTaskCode]							AS [rbk_ProjectTask],
pta.ProjectTaskCode																	AS [ProjectTaskId],  
pta.ProjectTaskName																	AS [ProjectTaskName], 

act.ActivityNumber																	AS [ActivityId],
act.ActivityName																	AS [ActivityName], 
tr.InterCompanyId																	AS [InterCompanyId], 
e.Domain																			AS [EmployeeDomain],
e.Login																				AS [EmployeeLogin],
e.[Domain]+'/'+e.[Login]															AS [EmployeeLoginId],
ISNULL(e.PreferredFirstName,e.Firstname)											AS [EmployeeFirstName],	
e.lastname																			AS [EmployeeLastName],	
e.FirstNameLastName																	AS [EmployeeFullName],	
emp.[EmploymentContractTypeKey]														AS [EmploymentContractTypeID],
ect.[EmploymentContractTypeName]													AS [EmploymentContractTypeName], 
ago.AccountGroupOperationalId														AS [AccountGroupOperationalId],
ago.AccountGroupOperationalName														AS [AccountGroupOperationalName],
mago.MainAccountGroupOperationalId													AS [MainAccountGroupOperationalId],
mago.MainAccountGroupOperationalName												AS [MainAccountGroupOperationalName],
agp.AccountGroupProjectId															AS [AccountGroupProjectId],
agp.AccountGroupProjectName															AS [AccountGroupProjectName],
magp.MainAccountGroupProjectId														AS [MainAccountGroupProjectId],
magp.MainAccountGroupProjectName													AS [MainAccountGroupProjectName],
0																					AS [AccountGroupAnalyticalId],					-- To be filled with analytical account group id
'All accounts'																		AS [AccountGroupAnalyticalName],				-- To be filled with analytical account group name
mago.ApplyPLselfcostProjSign														AS [Apply_HoursSign_for_PnL],					-- Yes, there is no separate flag for this
mago.ApplyPLselfcostProjSign														AS [Apply_ProjCostSign_for_PnL],
magp.ApplyProjRecIncomeSign															AS [Apply_RevenueSign_for_ProjectReports],
ac.ProjRecIncomeSign																AS [RevenueSign_for_ProjectReports],
ac.PLhoursSign																		AS [HoursSign_for_PnL],
ac.PLselfcostProjSign																AS [ProjCostSign_for_PnL],		
t.BusinessAreaId																	AS [Team_BusinessAreaId],
tba.BusinessAreaName																AS [Team_BusinessAreaName],

t.BusinessAreaId+'/'+t.DivisionId													AS [rbk_Team_Division],							-- New rbk
t.DivisionId																		AS [Team_DivisionId],
tdiv.DivisionName																	AS [Team_DivisionName],

t.BusinessAreaId+'/'+t.BusinessUnitId												AS [rbk_Team_BusinessUnit],						-- New rbk
t.BusinessUnitId																	AS [Team_BusinessUnitId],
tbu.BusinessUnitName																AS [Team_BusinessUnitName],

t.BusinessAreaId+'/'+t.DepartmentId													AS [rbk_Team_Department],						-- New rbk
t.DepartmentId																		AS [Team_DepartmentId],
tdep.DepartmentName																	AS [Team_DepartmentName],

tLoc.CountryAlpha2Code																AS [Team_CountryId],
tLoc.CountryName																	AS [Team_CountryName],
t.CompanyId																			AS [Team_CompanyId],
tc.CompanyName																		AS [Team_CompanyName],

cc.CompanyId+'/'+ct.TeamId															AS [rbk_CounterpartTeam],						-- New rbk
ct.TeamId																			AS [CounterpartTeamId],
ct.TeamName																			AS [CounterpartTeamName],
ct.BusinessAreaId																	AS [CounterpartTeam_BusinessAreaId],
ctba.BusinessAreaName																AS [CounterpartTeam_BusinessAreaName],

ct.BusinessAreaId+''+ct.DivisionId													AS [rbk_CounterpartTeam_Division],				-- New rbk
ct.DivisionId																		AS [CounterpartTeam_DivisionId],
ctdiv.DivisionName																	AS [CounterpartTeam_DivisionName],

ct.BusinessAreaId+'/'+ct.BusinessUnitId												AS [rbk_CounterpartTeam_BusinessUnit],			-- New rbk
ct.BusinessUnitId																	AS [CounterpartTeam_BusinessUnitId],
ctbu.BusinessUnitname																AS [CounterpartTeam_BusinessUnitName],

ct.BusinessAreaId+'/'+ct.DepartmentId												AS [rbk_CounterpartTeam_Department],			-- New rbk
ct.DepartmentId																		AS [CounterpartTeam_DepartmentId],
ctdep.DepartmentName																AS [CounterpartTeam_DepartmentName],
cLoc.CountryAlpha2Code																AS [CounterpartTeam_CountryId],
cLoc.CountryName																	AS [CounterpartTeam_CountryName],
ct.CompanyId																		AS [CounterpartTeam_CompanyId],
cc.CompanyName																		AS [CounterpartTeam_CompanyName],
CASE 
	WHEN t.BusinessAreaId	<> ct.BusinessAreaId THEN 'Cross BA'
	WHEN t.DivisionId		<> ct.DivisionId THEN 'Cross division'
	WHEN t.BusinessUnitId	<> ct.BusinessUnitId THEN 'Cross BU'
	WHEN t.DepartmentId		<> ct.DepartmentId THEN 'Cross department'	
	WHEN t.TeamId			<> ct.TeamId THEN 'Cross Team'
END																					AS [CollaborationTypeOperational],
CASE 
	WHEN tLoc.CountryAlpha2Code	<> cLoc.CountryAlpha2Code THEN 'Cross border'
	WHEN tc.CompanyId		<> cc.CompanyId THEN 'Intercompany'
END																					AS [CollaborationTypeLegal],
tr.[Amount]																			AS [Amount], 
u.CurrencyCode																		AS [CurrencyCode],
tr.[Count]																			AS [Count], 
tr.[Text]																			AS [Text], 
tr.[ValueTypeKey]																	AS [ValueTypeId],
evt.[ValueTypeName]																	AS [ValueTypeName],
tr.[LegacyAccountId]																AS [LegacyAccountId],  
tr.[InstanceKey]																	AS [InstanceKey], 
tr.[PostedBy]																		AS [PostedBy], 
tr.[src_ChangedTime]																AS [src_ChangedTime], 
tr.[md_InsertedTime]																AS [md_InsertedTime], 
tr.[md_InsertedBy]																	AS [md_InsertedBy], 
tr.[md_ChangedTime]																	AS [md_ChangedTime], 
tr.[md_ChangedBy]																	AS [md_ChangedBy], 
tr.[md_RowVersion]																	AS [md_RowVersion], 
tr.[md_RowState]																	AS [md_RowState], 
tr.[md_SourceId]																	AS [md_SourceId], 
tr.[md_StgRowId]																	AS [md_StgRowId], 
tr.[md_LoadJobId]																	AS [md_LoadJobId], 
tr.[md_DqLevel]																		AS [md_DqLevel], 
tr.[md_DqIssueDescription]															AS [md_DqIssueDescription],
tr.[md_BD]																			AS [md_BD],
tr.[md_BPK]																			AS [md_BPK],
tr.[TransactionKey]																	AS [EcoTransactionKey]

FROM CoreData.EcoTransaction					tr
JOIN CoreData.OrgCompany						c		ON tr.CompanyId = c.CompanyId
LEFT JOIN CoreData.EcoCurrency					u		ON u.CurrencyKey = c.CurrencyKey
LEFT JOIN CoreData.EcoTransactionType			tt		ON tt.TransactionTypeKey = tr.TransactionTypeKey					-- NEW 2021-09-06
-- Account dimensions
LEFT JOIN CoreData.EcoAccountChart				ac		ON ac.Accountchartid = c.Accountchartid
LEFT JOIN CoreData.EcoAccount					a		ON tr.AccountId = a.AccountID and ac.Accountchartkey = a.Accountchartkey
LEFT JOIN CoreData.EcoMainaccount				ma		ON a.MainAccountKey = ma.MainAccountKey
LEFT JOIN CoreData.EcoAccountGroupOperational		AS ago	ON ma.AccountGroupOperationalKey = ago.AccountGroupOperationalKey
LEFT JOIN CoreData.EcoMainAccountGroupOperational	AS mago	ON ago.MainAccountGroupOperationalKey = mago.MainAccountGroupOperationalKey
LEFT JOIN CoreData.EcoAccountGroupProject		agp		ON agp.AccountGroupProjectKey = a.AccountGroupProjectKey
LEFT JOIN CoreData.EcoMainAccountGroupProject	magp	ON magp.MainAccountGroupProjectKey = agp.MainAccountGroupProjectKey
-- Project organisation
LEFT JOIN CoreData.Project						p		ON tr.ProjectKey = p.ProjectKey
LEFT JOIN CoreData.OrgTeam						pt		ON p.TeamKey = pt.TeamKey
LEFT JOIN CoreData.OrgCompany					pc		ON p.CompanyId = pc.CompanyId		
LEFT JOIN CoreData.ProjectTask					pta		ON tr.TaskName = pta.ProjectTaskCode and pta.ProjectKey = p.ProjectKey
LEFT JOIN CoreData.Activity						act		ON tr.ActivityNumber = act.ActivityNumber
-- Team organisation
LEFT JOIN CoreData.OrgTeam						t		ON tr.TeamKey = t.TeamKey
LEFT JOIN CoreData.OrgDepartment				tdep	ON t.DepartmentId = tdep.DepartmentId and t.BusinessAreaId = tdep.BusinessAreaId
LEFT JOIN CoreData.OrgBusinessUnit				tbu		ON t.BusinessUnitId = tbu.BusinessUnitId and t.BusinessAreaId = tbu.BusinessAreaId
LEFT JOIN CoreData.OrgDivision					tdiv	ON t.DivisionId = tdiv.DivisionId and t.BusinessAreaId = tdiv.BusinessAreaId
LEFT JOIN CoreData.OrgBusinessArea				tba		ON t.BusinessAreaId = tba.BusinessAreaId
LEFT JOIN CoreData.OrgCompany					tc		ON t.CompanyId = tc.CompanyId
LEFT JOIN CoreData.LocCountry					tLoc	ON c.CountryId = tLoc.CountryKey
-- Counterpart team organisation
LEFT JOIN CoreData.OrgTeam						ct		ON tr.CounterpartTeamKey = ct.TeamKey						
LEFT JOIN CoreData.OrgDepartment				ctdep	ON ct.DepartmentId = ctdep.DepartmentId and ct.BusinessAreaId = ctdep.BusinessAreaId
LEFT JOIN CoreData.OrgBusinessUnit				ctbu	ON ct.BusinessUnitId = ctbu.BusinessUnitId and ct.BusinessAreaId = ctbu.BusinessAreaId
LEFT JOIN CoreData.OrgDivision					ctdiv	ON ct.DivisionId = ctdiv.DivisionId and ct.BusinessAreaId = ctdiv.BusinessAreaId
LEFT JOIN CoreData.OrgBusinessArea				ctba	ON ct.BusinessAreaId = ctba.BusinessAreaId
LEFT JOIN CoreData.OrgCompany					cc		ON ct.CompanyId = cc.CompanyId
LEFT JOIN CoreData.LocCountry					cLoc	ON cc.CountryId = cLoc.CountryKey
-- Employee dimensions
LEFT JOIN CoreData.Employee						e		ON tr.EmployeeKey = e.EmployeeKey
LEFT JOIN CoreData.Employment					emp		ON e.EmployeeKey = emp.Employeekey 
LEFT JOIN CoreData.EmploymentContractType		ect		ON emp.EmploymentKey = ect.EmploymentContractTypeKey
LEFT JOIN CoreData.EcoValueType					evt		ON evt.ValueTypeId = tr.ValueTypeKey
GO
/****** Object:  View [CoreX].[OrganisationAllLevels]    Script Date: 2025-07-16 15:57:21 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/*
================================================================= 

View name:	[CoreX].[OrganisationAllLevels]

Purpose:	All organisational units regardless of status or level.

Content:	Unitid (team number, company number, division code etc), and unitlevelid. 
			Id for all parent units. 
			Country (for teams and companies only).
			Managers directly appointed on the given unit (not inherited).

Sensitive:	Restricted - Contains personal information. May be shared within Sweco.

Hints:		bk_OrgUnitId uniquely identifies unit and level. 
			Filter on Active = 1 to select current units only.
			Filter on UnitLevelId (or name) to select a given level only.
			Use rbk-columns as join key against other organisation views' bk-columns.
			

================================================================= 

Changes:  
	2022-02-14	SEARNO	Core 5.3: CoreData.Employee instead of dbo	
	2022-07-20	SEARNO	Added AllowStandardDataTransfer for 3rd country transfer control. It shows 0 for teams not to be nested in AD organisation groups other than for higher units also having 0, meaning their teams are all from 3rd country.
	2022-09-07	SEMLJS	Changed name of column AllowStandardDataTransfer to AllowGDPR3rdCountryDataTransfer
	2025-02-03	SESHET	Added TeamBudgetTypeId,TeamBudgetTypeName, EstablishmentNo, Street, UnitLevelId, UnitLevelName
	2025-02-24	SEMBOD	Changed TeamBudgetTypeId and MgmtTeamUnitlevelId from '' to NULL, since datatype is int. For other non team levels
	2025-05-07	SEVEWP	Added UnitKey
================================================================= 

SELECT TOP 10 * FROM [CoreX].[OrganisationAllLevels] WHERE Active = 1 AND UnitLevelId = 2
SELECT * FROM [CoreX].[OrganisationAllLevels] WHERE AllowStandardDataTransfer IS NULL order by 1


*/ 

CREATE VIEW [CoreX].[OrganisationAllLevels] AS


/* OrganisationAllLevels*/

SELECT DISTINCT

ot.[OrgUnitId]																													AS [bk_OrgUnit],					  
ot.[ParentOrgUnitId]																											AS [ParentOrgUnitId],					  
5																																AS [UnitLevelId], 
'Team'																															AS [UnitLevelName], 
ot.[BusinessAreaId]																												AS [BusinessAreaID], 
ot.[BusinessAreaId]+'/'+ot.[DivisionId]																							AS [rbk_Division],
ot.[DivisionId]																													AS [DivisionID],  
ot.[BusinessAreaId]+'/'+ot.[BusinessUnitId]																						AS [rbk_BusinessUnit],
ot.[BusinessUnitId]																												AS [BusinessUnitID], 
ot.[BusinessAreaId]+'/'+ot.[DepartmentId]																						AS [rbk_Department],
ot.[DepartmentId]																												AS [DepartmentID],
ot.[CompanyId]+'/'+ot.[TeamId]																									AS [rbk_Team],
ot.[TeamId]																														AS [TeamId],  
ot.[CompanyId]																													AS [CompanyID], 
co.[CountryAlpha2Code]																											AS [CountryCode],						
co.[CountryName]																												AS [CountryName],		
ot.[CompanyId]																													AS [ParentId],						
ot.[TeamId]																														AS [UnitId],						
ot.[TeamName]																													AS [UnitName],						
CAST(co.AllowGDPR3rdCountryDataTransfer as int) 																				AS [AllowGDPR3rdCountryDataTransfer],
ot.[Active]																														AS [Active],  
ot.[ValidFromDate]																												AS [ValidFromDate],  
ot.[ValidToDate]																												AS [ValidToDate],  
e.[Login]																														AS [ManagerId],						
e.FirstNameLastName																												AS [ManagerName],					
otb.TeamBudgetTypeId                                                                                                            AS [TeamBudgetTypeId],
otb.TeamBudgetTypeName                                                                                                          AS [TeamBudgetTypeName],
loa.EstablishmentNo                                                                                                             AS [FMteamOfficeId],
loa.Street                                                                                                                      AS [FMteamOfficeName],
oul.UnitLevelId                                                                                                                 AS [MgmtTeamUnitlevelId],
oul.UnitLevelName                                                                                                               AS [MgmtTeamUnitlevelName],
ot.[md_InsertedTime]																											AS [md_InsertedTime],  
ot.[md_InsertedBy]																												AS [md_InsertedBy],  
ot.[md_ChangedTime]																												AS [md_ChangedTime],  
ot.[md_ChangedBy]																												AS [md_ChangedBy],  
ot.[md_RowVersion]																												AS [md_RowVersion], 
ot.[md_RowState]																												AS [md_RowState],  
ot.[md_SourceId]																												AS [md_SourceId],  
ot.[md_StgRowId]																												AS [md_StgRowId],  
ot.[md_LoadJobId]																												AS [md_LoadJobId],  
ot.[md_DqLevel]																													AS [md_DqLevel],  
ot.[md_DqIssueDescription]																										AS [md_DqIssueDescription],
ot.[TeamKey]																													AS [UnitKey]
FROM CoreData.OrgTeam					AS ot

LEFT JOIN CoreData.OrgCompany			AS c	ON ot.CompanyId = c.CompanyId
LEFT JOIN [CoreData].[OrgTeamManager]	AS tm	ON ot.CompanyId = tm.CompanyID AND ot.TeamId = tm.TeamID
LEFT JOIN [CoreData].[Employee]			AS e	ON e.EmployeeKey = tm.Employee1  
LEFT JOIN [CoreData].[LocCountry]		AS co	ON c.CountryId = co.CountryKey
LEFT JOIN [CoreData].[OrgTeamBudgetType] AS otb  ON otb.TeamBudgetTypeKey=ot.TeamBudgetTypeKey
LEFT JOIN [CoreData].[LocOfficeAddress] AS loa  ON loa.AddressKey=ot.FMteamOfficeKey
LEFT JOIN [CoreData].[OrgUnitLevel]     AS oul  ON oul.UnitLevelKey=ot.MgmtTeamUnitLevelKey


UNION 

SELECT DISTINCT

d.[OrgUnitId]																													AS [bk_OrgUnit],					
d.[ParentOrgUnitId]																												AS [ParentOrgUnitId],					  
4																																AS [UnitLevelId], 
'Department'																													AS [UnitLevelName], 
d.[BusinessAreaId]																												AS [BusinessAreaID], 
d.[BusinessAreaId]+'/'+d.[DivisionId]																							AS [rbk_Division],
d.[DivisionId]																													AS [DivisionID],  
d.[BusinessAreaId]+'/'+d.[BusinessUnitId]																						AS [rbk_BusinessUnit],
d.[BusinessUnitId]																												AS [BusinessUnitID],  
d.[BusinessAreaId]+'/'+d.[DepartmentId]																							AS [rbk_Department],
d.[DepartmentId]																												AS [DepartmentID],  
''																																AS [rbk_Team],
''																																AS [TeamId],  
''																																AS [CompanyID], 
''																																AS [CountryCode],
''																																AS [CountryName],
d.[BusinessAreaId]																												AS [ParentId],						
d.[DepartmentId]																												AS [UnitId],						
d.[DepartmentName]																												AS [UnitName],						
MAX(CAST(co.AllowGDPR3rdCountryDataTransfer as int) ) OVER(PARTITION BY d.[BusinessAreaId], d.[DepartmentId])					AS [AllowGDPR3rdCountryDataTransfer],
d.[Active]																														AS [Active],  
d.[ValidFromDate]																												AS [ValidFromDate],  
d.[ValidToDate]																													AS [ValidToDate],  
e.[Login]																														AS [ManagerId],						
e.FirstNameLastName																												AS [ManagerName],
NULL																															AS [TeamBudgetTypeId],
''																																AS [TeamBudgetTypeName],
''                                                                                                                              AS [FMteamOfficeId],
''                                                                                                                        		AS [FMteamOfficeName],
NULL																															AS [MgmtTeamUnitlevelId],
''																																AS [MgmtTeamUnitlevelName],
d.[md_InsertedTime]																												AS [md_InsertedTime],  
d.[md_InsertedBy]																												AS [md_InsertedBy],  
d.[md_ChangedTime]																												AS [md_ChangedTime],  
d.[md_ChangedBy]																												AS [md_ChangedBy],  
d.[md_RowVersion]																												AS [md_RowVersion], 
d.[md_RowState]																													AS [md_RowState],  
d.[md_SourceId]																													AS [md_SourceId],  
d.[md_StgRowId]																													AS [md_StgRowId],  
d.[md_LoadJobId]																												AS [md_LoadJobId],  
d.[md_DqLevel]																													AS [md_DqLevel],  
d.[md_DqIssueDescription]																										AS [md_DqIssueDescription],
d.[DepartmentKey]																												AS [UnitKey]
FROM [CoreData].[OrgDepartment]		AS d

LEFT JOIN CoreData.OrgTeam			AS t	ON d.DepartmentId = t.DepartmentId AND d.BusinessAreaId = t.BusinessAreaId
