/*
================================================================= 

View name:	[CoreX].[OrgTeam]

Purpose:	All active teams with info about the organisation structure and team manager

Content:	Id and name for teams and all parent units. Directly appointed team managers (not inherited).

Sensitive:	Restricted - Contains personal information. May be shared within Sweco.

Hints:		Filter on Active = 1 to select the current team list.
			Use rbk-columns as join key against other organisation views' bk-columns.


================================================================= 

Changes:  
			2022-02-14	SEARNO	Core 5.3: Join on coredata.LocCountry and Coredata.Employee instead of dbo	
			2022-06-03	SEMBOD	Added CountryName
			2022-07-20	SEARNO	Added AllowStandardDataTransfer for 3rd country transfer control
			2022-09-07	SEMLJS	Changed name of column AllowStandardDataTransfer to AllowGDPR3rdCountryDataTransfer
================================================================= 

SELECT TOP 10 * FROM [CoreX].[OrgTeam]

*/ 

CREATE   VIEW [CoreX].[OrgTeam]
AS
SELECT
t.CompanyId+'/'+t.TeamId					AS [bk_Team],
c.[CompanyId]								AS [CompanyId], 
c.[CompanyName]								AS [CompanyName], 
t.[TeamId]									AS [TeamId], 
t.[TeamName]								AS [TeamName], 
ba.[BusinessAreaId]							AS [BusinessAreaId], 
ba.[BusinessAreaName]						AS [BusinessAreaName], 
d.[BusinessAreaId]+'/'+d.[DivisionId]		AS [rbk_Division],
d.[DivisionId]								AS [DivisionId], 
d.[DivisionName]							AS [DivisionName], 
bu.[BusinessAreaId]+'/'+bu.[BusinessUnitId]	AS [rbk_BusinessUnit],
bu.[BusinessUnitId]							AS [BusinessUnitId], 
bu.[BusinessUnitName]						AS [BusinessUnitName], 
dep.[BusinessAreaId]+'/'+dep.[DepartmentId]	AS [rbk_Department],		
dep.[DepartmentId]							AS [DepartmentId], 
dep.[DepartmentName]						AS [DepartmentName], 
lc.CountryAlpha2Code						AS [CountryCode], 
lc.CountryName								AS [CountryName], 
e.[Domain]									AS [TeamManagerDomain], 
e.[Login]									AS [TeamManagerLogin],		
e.[Domain]+'/'+e.[Login]					AS [TeamManagerLoginId],
ISNULL(e.PreferredFirstName,e.Firstname)	AS [TeamManagerFirstName],
e.lastname									AS [TeamManagerLastName], 
e.FirstNameLastName							AS [TeamManagerFullName],
t.[Active]									AS [Active],
lc.AllowGDPR3rdCountryDataTransfer			AS [AllowGDPR3rdCountryDataTransfer],
t.[md_ChangedBy]							AS [src_ChangedBy],
t.[md_ChangedTime]							AS [src_ChangedTime],
t.[md_InsertedTime]							AS [md_InsertedTime],
t.[md_InsertedBy]							AS [md_InsertedBy],
t.[md_ChangedTime]							AS [md_ChangedTime],
t.[md_ChangedBy]							AS [md_ChangedBy], 
t.[md_RowVersion] 							AS [md_RowVersion], 
t.[md_RowState] 							AS [md_RowState], 
t.[md_SourceId] 							AS [md_SourceId], 
t.[md_StgRowId] 							AS [md_StgRowId], 
t.[md_LoadJobId] 							AS [md_LoadJobId], 
t.[md_DqLevel]	 							AS [md_DqLevel], 
t.[md_DqIssueDescription]					AS [md_DqIssueDescription], 
t.[md_BD]									AS [md_BD],
t.[md_BPK]									AS [md_BPK],
t.[TeamKey]									AS [TeamKey]
FROM CoreData.OrgTeam				t
JOIN CoreData.OrgCompany			c	ON t.CompanyId = c.CompanyId
LEFT JOIN CoreData.OrgBusinessArea	ba	ON t.BusinessAreaId = ba.BusinessAreaId
LEFT JOIN CoreData.OrgDivision		d	ON t.DivisionId = d.DivisionId and t.BusinessAreaId = d.BusinessAreaId
LEFT JOIN CoreData.OrgBusinessUnit	bu	ON t.BusinessUnitId = bu.BusinessUnitId and t.BusinessAreaId = bu.BusinessAreaId
LEFT JOIN CoreData.OrgDepartment	dep	ON t.DepartmentId = dep.DepartmentId and t.BusinessAreaId = dep.BusinessAreaId
LEFT JOIN CoreData.LocCountry		lc	ON c.CountryId = lc.CountryKey
LEFT JOIN CoreData.OrgTeamManager	otm	ON t.TeamId = otm.TeamID and t.CompanyId = otm.CompanyID -- TeamKey?
LEFT JOIN CoreData.Employee			e	On coalesce(otm.Employee1,otm.Employee2,otm.Employee3,otm.Employee4,otm.Employee5,otm.Employee6,otm.Employee7,otm.Employee8,otm.Employee9,otm.Employee10) = e.EmployeeKey
GO
