CREATE   VIEW [dbo].[EcoWorkTime] 
AS			

SELECT 

ewc.[CompanyId]			AS		[CompanyID],
ewc.[WorkYearMonth]		AS		[Period], 
ewc.[WorkTimeHours]		AS		[Worktime],
evt.[ValueTypeId]		AS		[ValueTypeId]

FROM [CoreData].[EcoWorkCalendar]		AS			ewc
LEFT JOIN [CoreData].[EcoValueType]		AS			evt		ON ewc.ValueTypeKey = evt.ValueTypeKey;
